/**
 * checkArg
 * @param {String} argument
 * @param {Array<WebCLGLKernel>} kernels
 * @param {Array<WebCLGLVertexFragmentProgram>} vfps
 * @returns {Object}
 */
bool NCLGLFor::checkArg(std::string argument) {
    bool usedByKernelPr = false;
    bool usedInVertex = false;
    bool usedInFragment = false;

    for(int n=0; n < kernelsCount; n++) {
        for(int nb=0; nb < kernels[n]._inValuesCount; nb++) {
            if(strcmp(kernels[n].in_values[nb].varnameC.c_str(), argument.c_str())==0) {
                usedByKernelPr = true;
                break;
            }
        }
    }

    for(int n=0; n < vertexFragmentProgramsCount; n++) {
        for(int nb=0; nb < vertexFragmentPrograms[n]._v_inValuesCount; nb++) {
            if(strcmp(vertexFragmentPrograms[n].in_vertex_values[nb].varnameC.c_str(), argument.c_str())==0) {
                usedInVertex = true;
                break;
            }
        }
        for(int nb=0; nb < vertexFragmentPrograms[n]._f_inValuesCount; nb++) {
            if(strcmp(vertexFragmentPrograms[n].in_fragment_values[nb].varnameC.c_str(), argument.c_str())==0) {
                usedInFragment = true;
                break;
            }
        }
    }

    return (!usedByKernelPr && usedInVertex && !usedInFragment);
};

void NCLGLFor::setArg(char *argument, float *uniform1fValue, float *uniformArrayFValue, int valueLength, float * overrideDimensions) {
    for(int n=0; n < argsValuesCount; n++) {
        std::vector<std::string> expl = NCLGLUtils::split(_argsValues[n].entireVarnameC, std::string(" "));
        if(expl.size() > 1) {
            std::string completeVarName = expl[1];

            std::vector<std::string> explB = NCLGLUtils::split(completeVarName, std::string("[")); // replace(/\[\d.*/, "")
            std::string completeVarNameNoB = explB[0];

            if(strcmp(completeVarNameNoB.c_str(), argument)==0) {
                char *completeVarName_c = new char[completeVarName.length() + 1];
                strcpy(completeVarName_c, completeVarName.c_str());

                if(strcmp(completeVarName_c, argument)==0)
                    setArgNow(_argsValues[n].entireVarnameC, argument, uniform1fValue, uniformArrayFValue, valueLength, overrideDimensions);
                else
                    setArgNow(_argsValues[n].entireVarnameC, completeVarName_c, uniform1fValue, uniformArrayFValue, valueLength, overrideDimensions);

                //         if(this.calledArgs.hasOwnProperty(argument) === true) {
                //             for(let n=0; n < this.calledArgs[argument].length; n++) {
                //                 let gpufor = this.calledArgs[argument][n];
                //                 gpufor._argsValues[argument] = this._argsValues[argument];
                //
                //                 Module.ccall("getGPUForArg", null, ["number", "string", "number"],
                //                     [gpufor.id, argument, this.id]);
                //             }
                //         }

                break;
            }
        }
    }
}

void NCLGLFor::setArgNow(std::string entireVarnameC, char *argument, float *uniform1fValue, float *uniformArrayFValue, int valueLength, float * overrideDimensions) {
    #if DEBUG
        printf("[WasmCLGLFor setArgNow]  %s\n", argument);
    #endif

    std::vector<std::string> expl = NCLGLUtils::split(std::string(entireVarnameC), std::string("*"));
    if(expl.size() > 1) {
        // buffer
        std::string mode(checkArg(std::string(argument)) ? "ATTRIBUTE" : "SAMPLER");

        std::string type(toupper(expl[0]));

        setArgBuffer(argument, type, false, mode, uniformArrayFValue, valueLength, false, overrideDimensions);
    } else {
        // UNIFORM
        setArgUniform(argument, uniform1fValue, uniformArrayFValue, valueLength);
    }
}
void NCLGLFor::setArgBuffer(char *argument, std::string type, bool linear, std::string mode, float *value, int valueLength, bool flip, float * overrideDimensions) {
    // BUFFER
    int ex = argExists(argument);
    if(ex == -1) {
        NCLGLArgValue _argsVal = NCLGLArgValue();
        _argsVal.varnameC = std::string(argument);
        _argsVal.type = type;
        _argsVal.linear = linear;
        _argsVal.mode = mode;
        _argsVal.flip = flip;
        NCLGLBuffer buff = wasmclgl->createBuffer(); // type="FLOAT"|"FLOAT4", linear, mode="SAMPLER"|"ATTRIBUTE"|"VERTEX_INDEX"
        buff.ini(_argsVal.type, linear, mode);
        _argsVal.f32Val = buff;

        #if DEBUG
            printf("[WasmCLGLFor setArgBuffer] CREATE %s %s %s...\n", argument, _argsVal.mode.c_str(), _argsVal.type.c_str());
        #endif
        _argsVal.f32Val.writeBuffer(value, valueLength, false, overrideDimensions);

        _argsVal.bufferIsReady = true;
        _argsValues[argsValuesCount] = _argsVal;
        argsValuesCount++;
    } else {
        _argsValues[ex].varnameC = std::string(argument);
        _argsValues[ex].type = type;
        _argsValues[ex].linear = linear;
        _argsValues[ex].mode = mode;
        _argsValues[ex].flip = flip;
        NCLGLBuffer buff = wasmclgl->createBuffer(); // type="FLOAT"|"FLOAT4", linear, mode="SAMPLER"|"ATTRIBUTE"|"VERTEX_INDEX"
        buff.ini(_argsValues[ex].type, linear, mode);
        _argsValues[ex].f32Val = buff;

        #if DEBUG
            printf("[WasmCLGLFor setArgBuffer] UPDATING %s %s %s %d %d ... \n", argument, _argsValues[ex].mode.c_str(), _argsValues[ex].type.c_str(), (int)overrideDimensions[0], (int)overrideDimensions[1]);
        #endif
        _argsValues[ex].f32Val.writeBuffer(value, valueLength, false, overrideDimensions);
    }
}
void NCLGLFor::setArgNull(char *argument) {
    // NULL
    #if DEBUG
        printf("[WasmCLGLFor setArgNull] %s\n", argument);
    #endif
    int ex = argExists(argument);
    if(ex == -1) {
        NCLGLArgValue _argsVal = NCLGLArgValue();
        _argsVal.varnameC = std::string(argument);

        _argsValues[argsValuesCount] = _argsVal;
        argsValuesCount++;
    }
}
void NCLGLFor::setArgUniform(char *argument, float *uniform1fValue, float *uniformArrayFValue, int valueLength) {
    // UNIFORM
    #if DEBUG
        printf("[WasmCLGLFor arguniform] %s %f \n", argument, *uniform1fValue);
    #endif
    int ex = argExists(argument);
    if(ex == -1) {
        NCLGLArgValue _argsVal = NCLGLArgValue();
        _argsVal.varnameC = std::string(argument);
        _argsVal.uniformVal = *uniform1fValue;
        _argsVal.uniformArrayVal = uniformArrayFValue;
        _argsVal.uniformArrayValLength = valueLength;

        _argsValues[argsValuesCount] = _argsVal;
        argsValuesCount++;
    } else {
        _argsValues[ex].uniformVal = *uniform1fValue;
        _argsValues[ex].uniformArrayVal = uniformArrayFValue;
        _argsValues[ex].uniformArrayValLength = valueLength;
    }
}
/**
 * Set indices for the geometry passed in vertexFragmentProgram
 * @param {Array<float>} arr
 */
void NCLGLFor::setArgIndices(char *argument, char *type, bool *linear, char *mode, uint16_t *value, int valueLength) {
    // INDICES
    #if DEBUG
        printf("[WasmCLGLFor setArgIndices] \n");
    #endif
    bufferIndices = wasmclgl->createBuffer();
    bufferIndices.ini(std::string(type), linear, std::string(mode)); // type="FLOAT"|"FLOAT4", linear, mode="SAMPLER"|"ATTRIBUTE"|"VERTEX_INDEX"
    bufferIndices.writeIndices(value, valueLength);
    bufferIndicesReady = true;
}

/**
 * getOutputBuffers
 * @param {WebCLGLKernel|WebCLGLVertexFragmentProgram} prog
 * @param {Array<WebCLGLBuffer>} buffers
 * @returns {Array<WebCLGLBuffer>}
 */
int NCLGLFor::getOutputBuffers(NCLGLKernel *prog, NCLGLBuffer *outputBuff) {
    int currentB = 0;
    if(strcmp(prog->_output[0].c_str(), "null")!=0) {
        for(int n=0; n < prog->_output.size(); n++) {
            for(int nb=0; nb < argsValuesCount; nb++) {
                if(strcmp(_argsValues[nb].varnameC.c_str(), prog->_output[n].c_str())==0) {
                    outputBuff[currentB] = _argsValues[nb].f32Val;

                    #if DEBUG
                        printf("[WasmCLGLFor getOutputBuffers] buff %d= %s \n", currentB, prog->_output[n].c_str());
                    #endif

                    currentB++;
                    break;
                }
            }
        }
    }

    return currentB;
}
/**
 * getOutputBuffers
 * @param {WebCLGLKernel|WebCLGLVertexFragmentProgram} prog
 * @param {Array<WebCLGLBuffer>} buffers
 * @returns {Array<WebCLGLBuffer>}
 */
int NCLGLFor::getOutputBuffersVFP(NCLGLVertexFragmentProgram *prog, NCLGLBuffer *outputBuff) {
    int currentB = 0;
    if(strcmp(prog->_output[0].c_str(), "null")!=0) {
        for(int n=0; n < prog->_output.size(); n++) {
            for(int nb=0; nb < argsValuesCount; nb++) {
                if(strcmp(_argsValues[nb].varnameC.c_str(), prog->_output[n].c_str())==0) {
                    outputBuff[currentB] = _argsValues[nb].f32Val;

                    #if DEBUG
                        printf("[WasmCLGLFor getOutputBuffersVFP] buff %d= %s \n", currentB, prog->_output[n].c_str());
                    #endif

                    currentB++;
                    break;
                }
            }

        }
    }

    return currentB;
}

void NCLGLFor::processKernels() {
    for(int n=0; n < kernelsCount; n++)
        processKernel(&kernels[n], true, false);

    if(kernelsCount > 0)
        processKernelCopies();
}

/**
 * Process kernels
 * @param {WebCLGLKernel} kernel
 * @param {boolean} [outputToTemp=null]
 * @param {boolean} [processCop]
 */
void NCLGLFor::processKernel(NCLGLKernel *kernel, bool outputToTemp, bool processCop) {
    if(kernel->enabled) {
        if(processCop)
            arrMakeCopyCount = 0;

        //kernel.drawMode
        (kernel->_depthTest) ? glEnable(GL_DEPTH_TEST) : glDisable(GL_DEPTH_TEST);

        (kernel->_blend) ? glEnable(GL_BLEND) : glDisable(GL_BLEND);

        glBlendFunc(kernel->_blendSrcMode, kernel->_blendDstMode);
        glBlendEquation(kernel->_blendEquation);

        bool tempsFound = false;
        for(int n=0; n < kernel->_output.size(); n++) {
            if(strcmp(kernel->_output[n].c_str(), "null")!=0) {
                tempsFound = true;
                break;
            }
        }


        int buffCount = getOutputBuffers(kernel, outputBuff);

        if(tempsFound) {
            #if DEBUG
                printf("[WasmCLGLFor processKernel] outputToTemp: true\n");
            #endif
            wasmclgl->enqueueNDRangeKernel(kernel, outputBuff, buffCount, true, _argsValues, argsValuesCount);
            arrMakeCopy[arrMakeCopyCount] = kernel;
            arrMakeCopyCount++;
        } else {
            #if DEBUG
                printf("[WasmCLGLFor processKernel] outputToTemp: false\n");
            #endif
            wasmclgl->enqueueNDRangeKernel(kernel, outputBuff, buffCount, false, _argsValues, argsValuesCount);
        }

        if(processCop)
            processKernelCopies();
    }
};

void NCLGLFor::processKernelCopies() {
    for(int n=0; n < arrMakeCopyCount; n++) {
        int buffCount = getOutputBuffers(arrMakeCopy[n], outputBuff);

        wasmclgl->copy(outputBuff, buffCount);
    }

    arrMakeCopyCount = 0;
};

/**
 * processGraphic
 * @param {String} [argumentInd=undefined] Argument for vertices count or undefined if argument "indices" exist
 **/
void NCLGLFor::processGraphic(std::string *argumentInd) {
   arrMakeCopyVFPCount = 0;
    for(int v=0; v < vertexFragmentProgramsCount; v++) {
        NCLGLVertexFragmentProgram *vfp = &vertexFragmentPrograms[v];

        if(vfp->enabled) {
            NCLGLBuffer *buff = nullptr;
            if(strcmp(argumentInd->c_str(), "null")==0 && bufferIndicesReady) {
                buff = &bufferIndices;
            } else {
                for(int nb=0; nb < argsValuesCount; nb++) {
                    if(strcmp(_argsValues[nb].varnameC.c_str(), argumentInd->c_str())==0) {
                        buff = &_argsValues[nb].f32Val;
                        break;
                    }
                }
            }

            (vfp->_depthTest) ? glEnable(GL_DEPTH_TEST) : glDisable(GL_DEPTH_TEST);

            (vfp->_blend) ? glEnable(GL_BLEND) : glDisable(GL_BLEND);

            glBlendFunc(vfp->_blendSrcMode, vfp->_blendDstMode);
            glBlendEquation(vfp->_blendEquation);

            bool tempsFound = false;
            for (int n = 0; n < vfp->_output.size(); n++) {
                if (strcmp(vfp->_output[n].c_str(), "null")!=0) {
                    tempsFound = true;
                    break;
                }
            }


            int buffCount = getOutputBuffersVFP(vfp, outputBuff);

            if (tempsFound) {
                #if DEBUG
                    printf("[WasmCLGLFor processGraphic] outputToTemp: true\n");
                #endif
                wasmclgl->enqueueVertexFragmentProgram(vfp, buff, &vfp->_drawMode, outputBuff, buffCount, true,
                                                       _argsValues, argsValuesCount);
                arrMakeCopyVFP[arrMakeCopyVFPCount] = vfp;
                arrMakeCopyVFPCount++;
            } else {
                #if DEBUG
                    printf("[WasmCLGLFor processGraphic] outputToTemp: false\n");
                #endif
                wasmclgl->enqueueVertexFragmentProgram(vfp, buff, &vfp->_drawMode, outputBuff, buffCount, false,
                                                       _argsValues, argsValuesCount);
            }

            //free(buff);
        }
    }

    for(int n=0; n < arrMakeCopyVFPCount; n++) {
        int buffCount = getOutputBuffersVFP(arrMakeCopyVFP[n], outputBuff);

        wasmclgl->copy(outputBuff, buffCount);
    }

    arrMakeCopyVFPCount = 0;
};

void NCLGLFor::enableKernel(int id) {
    kernels[id].enabled = true;
}

void NCLGLFor::disableKernel(int id) {
    kernels[id].enabled = false;
}

void NCLGLFor::enableGraphic(int id) {
    vertexFragmentPrograms[id].enabled = true;
}

void NCLGLFor::disableGraphic(int id) {
    vertexFragmentPrograms[id].enabled = false;
}

float * NCLGLFor::readBuffer(char *argument, float * outArr_ptr) {
    NCLGLBuffer *buff;
    for(int nb=0; nb < argsValuesCount; nb++) {
        if(strcmp(_argsValues[nb].varnameC.c_str(), argument)==0) {
            buff = &_argsValues[nb].f32Val;
            break;
        }
    }

    return wasmclgl->readBuffer(buff, outArr_ptr);
}

